<div class="page-header d-flex"><h2><?= e($invoice['invoice_number']) ?></h2><?php if ($invoice['status'] === 'issued'): ?><?= form_open('invoices/cancel/' . $invoice['id'], ['class' => 'ms-auto']) ?><button class="btn btn-danger" onclick="return confirm('<?= e(lang('confirm_cancel_invoice')) ?>')"><?= lang('cancel') ?></button><?= form_close() ?><?php endif; ?></div><div class="card"><div class="card-body"><p><?= lang('status') ?>: <?= e(lang($invoice['status'])) ?></p><table class="table"><thead><tr><th><?= lang('code') ?></th><th><?= lang('product') ?></th><th><?= lang('quantity') ?></th><th><?= lang('price') ?></th><th><?= lang('discount') ?></th><th><?= lang('total') ?></th></tr></thead><tbody><?php foreach ($invoice['items'] as $item): ?><tr><td><?= e($item['product_code']) ?></td><td><?= e($item['product_name']) ?></td><td><?= e($item['quantity']) ?></td><td><?= sar($item['unit_price']) ?></td><td><?= sar($item['discount_amount']) ?></td><td><?= sar($item['line_total']) ?></td></tr><?php endforeach; ?></tbody></table><h3><?= lang('total') ?>: <?= sar($invoice['total']) ?></h3></div></div>
